# Global attributes to ignore during comparison
EXCLUDE_GLOBAL_ATTRS = {"date_created", "history", "date_issued"}

# Comparison thresholds
ATOL = 1e-5  # Absolute tolerance
RTOL = 1e-5  # Relative tolerance
CHECK_ATTRIBUTES = True  # Compare global and variable metadata
